const PERSONALITY_TRAITS={gym:{name:'Gym Rat',group:'Work ethic',description:'Gains an extra development point in the offseason and softens regression.'},lazy:{name:'Complacent',group:'Work ethic',description:'Positive offseason development is halved; potential is harder to reach.'},smart:{name:'High Basketball IQ',group:'Work ethic',description:'Adds 5 effective offensive and defensive IQ points in games and improves team execution.'},steady:{name:'Steady Worker',group:'Work ethic',description:'Follows the standard development curve.'},leader:{name:'Leader / Mentor',group:'Locker room',description:'Raises younger teammates’ morale and adds a development point for teammates age 25 or younger.'},fiery:{name:'Fiery / Competitive',group:'Locker room',description:'Adds 3 skill points in playoffs and close late-game situations, with mild locker-room friction and a technical-foul risk.'},toxic:{name:'Toxic',group:'Locker room',description:'Lowers surrounding players’ morale and team chemistry.'},professional:{name:'Professional',group:'Locker room',description:'Keeps an even temperament without a special locker-room modifier.'},loyal:{name:'Loyal',group:'Business',description:'Accepts smaller raises, tolerates more unhappiness in negotiations, and offers a discount when returning to a former team.'},mercenary:{name:'Money-Chaser',group:'Business',description:'Demands at least a 20% raise on extensions and a 20% premium in free agency, regardless of team fit.'},diva:{name:'Spotlight Seeker',group:'Business',description:'Expects at least 36 minutes and a leading offensive role; sustained dissatisfaction increases the chance of expressing concerns or seeking a trade.'},balanced:{name:'Team & Business',group:'Business',description:'Balances compensation with role and team results.'}};
const TRAIT_GROUPS=[['gym','lazy','smart','steady'],['leader','fiery','toxic','professional'],['loyal','mercenary','diva','balanced']];
function generateTraits(p){let seed=(p.id+31)>>>0;for(const c of p.name)seed=(Math.imul(seed,31)+c.charCodeAt(0))>>>0;return TRAIT_GROUPS.map(g=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return g[(seed>>>16)%g.length]})}
function traitsOf(p){return p.personalityTraits||generateTraits(p)}
function hasTrait(p,key){return traitsOf(p).includes(key)}
function traitDevelopment(p,club,base){let delta=base;if(hasTrait(p,'gym'))delta++;if(hasTrait(p,'lazy')&&delta>0)delta=Math.floor(delta/2);if(p.age<=25&&club.roster.some(q=>q.id!==p.id&&hasTrait(q,'leader')))delta++;return delta}
function teammateMood(p,club){if(!club)return 0;return club.roster.reduce((s,q)=>s+(q.id===p.id?0:hasTrait(q,'toxic')?-4:hasTrait(q,'leader')&&p.age<=25?4:hasTrait(q,'fiery')?-1:0),0)}
function personalityCards(p){return playerCard('PERSONALITY',`<div class="personality-cards">${traitsOf(p).map(k=>{const t=PERSONALITY_TRAITS[k];return `<div><small>${t.group}</small><strong>${t.name}</strong><p>${t.description}</p></div>`}).join('')}</div>`)}
function freeAgentQuote(p,club=team()){const returning=hasTrait(p,'loyal')&&p.previousTeamKey===club.key;return Math.round(p.salary*(hasTrait(p,'mercenary')?1.2:returning?.95:1)*10)/10}
function personalityTechnicalFouls(clubs,rows,scores,log=()=>{},active=(club,p)=>rows.get(p.id).played){for(let side=0;side<2;side++)for(const p of clubs[side].roster){if(!active(clubs[side],p)||!hasTrait(p,'fiery')||Math.random()>=.05*(1-coachingSkill(clubs[side],'discipline')/130))continue;rows.get(p.id).tech++;const shooter=clubs[1-side].roster.filter(q=>active(clubs[1-side],q)).sort((a,b)=>b.attributes.ft-a.attributes.ft)[0],r=rows.get(shooter.id);log(side,p.name+' receives a technical foul.');r.fta++;if(Math.random()<.40+shooter.attributes.ft*.005){r.ftm++;r.pts++;scores[1-side]++;log(1-side,pbpNarrative('freeMade',{player:shooter.name}))}else log(1-side,pbpNarrative('freeMiss',{player:shooter.name}))}}
